const p=$json.body;const fail=error=>({json:{error}});
if(!p||typeof p!=='object'||Array.isArray(p))return fail('INVALID_DECISION');
if(typeof p.session_token!=='string'||!p.session_token.trim()||p.session_token.length>8192)return fail('INVALID_SESSION');
if(typeof p.candidate_id!=='string'||!p.candidate_id.trim()||p.candidate_id.length>256||typeof p.event_id!=='string'||!p.event_id.trim()||p.event_id.length>1024)return fail('INVALID_DECISION');
if(typeof p.request_id!=='string'||!/^[A-Za-z0-9_-]{1,100}$/.test(p.request_id)||!['offer','reject','on_hold','more_info'].includes(p.decision)||typeof p.notes!=='string'||!p.notes.trim()||p.notes.length>10000)return fail('INVALID_DECISION');
return {json:{sessionToken:p.session_token,candidateId:p.candidate_id,eventId:p.event_id,requestId:p.request_id,decision:p.decision,notes:p.notes}};

const d=$json;const expected=d.decision==='reject'?'rejected':d.decision;
const skipped=d.id!==d.latest_id||d.final_event_id!==d.event_id||d.stage!==expected;
const emails=d.decision==='more_info'?d.reviewer_emails:[d.candidate_email];
const invalid=!Array.isArray(emails)||emails.length===0||emails.some(e=>typeof e!=='string'||!/^\S+@[^\s@]+\.[^\s@]+$/.test(e));
const subjects={offer:'Next steps with your hiring team',reject:'Your application update',on_hold:'Your application is on hold',more_info:'Additional interview information requested'};
const messages={offer:'The hiring manager approved the next step. Your recruiter will contact you with the details.',reject:'The hiring team has decided not to proceed with your application. Thank you for your time.',on_hold:'Your application is currently on hold. Your recruiter will contact you when there is an update.',more_info:'The hiring manager requested more information for candidate '+d.candidate_id+'. Please review the decision notes in the staff portal.'};
const portal=d.decision==='more_info'?'<__PLACEHOLDER_VALUE__Staff interview review portal URL__>':'<__PLACEHOLDER_VALUE__Candidate interview portal URL__>';
return {json:{id:d.id,attempt:d.attempts,send:!skipped&&!invalid,status:skipped?'skipped':invalid?'pending':'processing',reason:skipped?'SUPERSEDED':invalid?'RECIPIENT_REQUIRED':null,recipient:invalid?'':emails.join(','),subject:subjects[d.decision],message:messages[d.decision]+'\n\n'+portal}};
